-- ENSURE ALL SEEDED EXPERT PROFILES ARE MARKED AS VERIFIED
UPDATE public.profiles SET is_verified = true WHERE role = 'expert';

SELECT count(*) AS total_verified_experts FROM public.profiles WHERE role = 'expert' AND is_verified = true;
